mapper.select:
SELECT COUNT(*) AS totalCnt, SUM(CASE WHEN vhcl_stts = '1' AND use_yn = 'Y' AND junk_yn = 'N' AND chck_stts IN ('0','1','2') THEN 1 ELSE 0 END) AS oprCnt FROM anls_vhcl_stts_rt where 1=1
and ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}

SELECT vhcl_sn , ownr_nm , reg_no , mt_id , lat , lng , chck_stts , CAST(AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) AS oprtr_nm , DATE_FORMAT(mdfcn_dt, '%Y-%m-%d %H:%i:%s') AS mdfcn_dt FROM anls_vhcl_stts_rt where 1=1
AND mt_id IN
#{mtId}
and ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}

SELECT SUM(CAST(opr_dstnc AS DECIMAL(10,2))) AS opr_dstnc, SUM(CAST(fuel_usage AS DECIMAL(10,2))) AS fuel_usage, SUM(CAST(cb AS DECIMAL(10,2))) AS cb, SUM(idle_tm) AS idle_tm FROM anls_vhcl_opr_hstry WHERE 1=1
AND anls_dt >= CURDATE() AND anls_dt < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
and ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}

SELECT DATE_FORMAT(anls_dt, '%m/%d') AS anls_dt, SUM(CAST(opr_dstnc AS DECIMAL(10,2))) AS opr_dstnc, ROUND(SUM(CAST(opr_dstnc AS DECIMAL(10,2))) / SUM(CAST(fuel_usage AS DECIMAL(10,2))), 2) AS fuel_econom, ROUND(SUM(CAST(cb AS DECIMAL(10,2))) / 1000, 2) AS cb, ROUND(SUM(idle_tm) / 3600, 2) AS idle_tm FROM anls_vhcl_opr_hstry WHERE 1=1
AND anls_dt >= DATE_SUB(CURDATE(), INTERVAL 8 DAY) AND anls_dt < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
and ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}
GROUP BY DATE(anls_dt) ORDER BY DATE(anls_dt) ASC

SELECT vhcl_sn , SUM(CAST(opr_dstnc AS DECIMAL(10,2))) AS opr_dstnc , ROUND(SUM(CAST(opr_dstnc AS DECIMAL(10,2))) / SUM(CAST(fuel_usage AS DECIMAL(10,2))), 2) AS fuelEconom , ROUND(SUM(CAST(cb AS DECIMAL(10,2))) / 1000, 2) AS cb , ROUND(SUM(idle_tm) / 3600, 2) AS idle_tm , SUM(ovr_spd_cnt) AS ovr_spd_cnt -- 과속수 , SUM(sud_dclr_cnt) AS sud_dclr_cnt -- 급감속수 , SUM(sud_accl_cnt) AS sud_accl_cnt -- 급가속수 , SUM(sud_stop_cnt) AS sud_stop_cnt -- 급정지수 , SUM(sud_strt_cnt) AS sud_strt_cnt -- 급출발수 , SUM(lng_ovr_spd_cnt) AS lng_ovr_spd_cnt -- 장기과속수 , SUM(rpm2000_ovr_cnt) AS rpm2000_ovr_cnt -- rpm2000초과수 FROM anls_vhcl_opr_hstry WHERE 1=1
AND anls_dt >= CURDATE() AND anls_dt < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
and ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}
GROUP BY vhcl_sn
